<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Correções da obra</title><link rel="stylesheet" href="/assets/css/app.css"><link rel="stylesheet" href="/assets/css/ui-v2.css"></head><body class="app-body"><div class="shell"><?php require __DIR__ . '/resources_sidebar.php'; ?><main class="content"><header class="topbar"><div><p class="eyebrow"><?=htmlspecialchars($work['condominium_name'])?></p><h1>Correções · Unidade <?=htmlspecialchars($work['unit'])?></h1><p class="muted">Envio de evidências pelo responsável e validação pelo fiscal.</p></div><a class="button secondary" href="/work?id=<?=(int)$work['id']?>">← Voltar</a></header><?php if(isset($_GET['submitted'])):?><div class="alert success">Correção enviada para validação.</div><?php endif;?><?php if(isset($_GET['reviewed'])):?><div class="alert success">Validação registrada.</div><?php endif;?><section class="panel"><div class="operation-list"><?php if(!$items):?><div class="empty-state"><p>Nenhuma não conformidade registrada nesta obra.</p></div><?php endif;?><?php foreach($items as $nc):?><article class="operation-card"><div class="row-gap"><strong><?=htmlspecialchars($nc['title'])?></strong><span class="badge"><?=htmlspecialchars($nc['status'])?></span></div><p><?=nl2br(htmlspecialchars($nc['description']))?></p><?php if($nc['corrective_deadline']):?><p><b>Prazo:</b> <?=htmlspecialchars($nc['corrective_deadline'])?></p><?php endif;?><?php if($nc['correction_notes']):?><div class="review-note"><b>Correção informada:</b><br><?=nl2br(htmlspecialchars($nc['correction_notes']))?></div><?php endif;?><?php foreach($evidence[(int)$nc['id']]??[] as $ev):?><p><a class="table-link" target="_blank" href="/work/non-conformity/evidence?id=<?=(int)$ev['id']?>">Ver evidência · <?=htmlspecialchars($ev['original_name'])?></a></p><?php endforeach;?><?php if($canSubmit && $nc['status']==='OPEN'):?><form method="post" action="/work/non-conformity/correction" enctype="multipart/form-data" class="form-stack"><input type="hidden" name="_token" value="<?=htmlspecialchars(Csrf::token())?>"><input type="hidden" name="non_conformity_id" value="<?=(int)$nc['id']?>"><label>O que foi corrigido?<textarea name="correction_notes" rows="3" required></textarea></label><label>Evidência (JPG, PNG ou PDF)<input type="file" name="evidence" accept="image/jpeg,image/png,application/pdf"></label><label>Legenda da evidência<input name="evidence_caption"></label><div class="form-actions"><button>Enviar correção</button></div></form><?php endif;?><?php if($canReview && $nc['status']==='CORRECTED'):?><form method="post" action="/work/non-conformity/correction/review" class="form-stack"><input type="hidden" name="_token" value="<?=htmlspecialchars(Csrf::token())?>"><input type="hidden" name="non_conformity_id" value="<?=(int)$nc['id']?>"><label>Observação do fiscal<textarea name="review_notes" rows="2"></textarea></label><div class="inline-actions"><button name="decision" value="APPROVE" class="button primary">Validar correção</button><button name="decision" value="RETURN" class="button warning">Devolver para ajuste</button></div></form><?php endif;?></article><?php endforeach;?></div></section></main></div></body></html>